def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    last_me, last_opp = history[-1]
    if n == 1 and last_opp == 'D':
        return 'D'
    opp_def = sum(1 for a, b in history if b == 'D')
    my_def = sum(1 for a, b in history if a == 'D')
    if last_opp == 'D':
        if opp_def * 100 <= n * 15 and my_def * 100 <= n * 20:
            return 'C'
        return 'D'
    return 'C'
